import type { MaterialIssue } from "../types";

const normalized = (value: unknown) => String(value || "").trim().toLowerCase();

/** Auto-generated production handoffs remain valid for stock/accounting but are not general consumable issues. */
export function isAutoProductionInterFirmIssue(issue: MaterialIssue) {
  return normalized(issue.interFirmFlow) === "yes"
    && normalized(issue.autoGenerated) === "yes"
    && normalized(issue.sourceTransactionType) === "production processing";
}

export function isDailyConsumableIssue(issue: Pick<MaterialIssue, "issueType">) {
  const type = normalized(issue.issueType);
  return type === "general" || type === "without job" || type === "withoutjob" || type === "without_job";
}

export function isPendingDailyConsumableTally(issue: MaterialIssue) {
  const tallyStatus = normalized(issue.tallyPostingStatus);
  return isDailyConsumableIssue(issue)
    && !String(issue.tallyTimestamp || "").trim()
    && tallyStatus !== "not applicable"
    && tallyStatus !== "cancelled"
    && !isAutoProductionInterFirmIssue(issue);
}
